tool.command:
python -c '
    import sys
    import anndata

    adata = anndata.read_h5ad('${input_file}')

    ${concatenate}
    ${obs_names_make_unique}
    ${var_names_make_unique}
    ${rename_categories}
    ${remove_keys}
    ${flag_genes_start_with_pattern}
    ${strings_to_categoricals}
    ${transpose}
    ${add_annotation}
    ${split}

    ${filter_observations}
    ${filter_variables}

    ${freeze_raw}

    adata.write_h5ad("${output_file}")
'
